mapper.select:
SELECT *
FROM t_event
WHERE id = #{eventId}
  AND state = 'ACTIVE';

mapper.update:
UPDATE t_event
SET consult_count = #{consultCount}
WHERE id = #{id};

mapper.select:
SELECT e.id AS id, f.path AS thumbNail, h.city AS city, h.district AS district, h.name AS hospitalName, e.name AS name, e.consult_count AS counselCount, e.price AS cost FROM t_event e JOIN t_hospital h ON h.id = e.hospital_id LEFT JOIN t_files f on e.image_group_id = f.group_id WHERE f.file_order = 1 AND e.state = 'ACTIVE' AND e.type = 'EVENT' AND e.date_started < NOW()::TIMESTAMPTZ AND e.date_end > NOW()::TIMESTAMPTZ
AND h.city = #{city}
AND h.district IN (
#{item}
)
AND e.category = #{category}
AND e.detail_category && array[ #{categoryDetail}::varchar ]
ORDER BY
${sort},
e.exposed_rank LIMIT #{size} OFFSET #{page} * #{size};

