	#{categoryDetail}::varchar
	]

mapper.update:
UPDATE t_event
SET view_count = view_count + 1
WHERE id = #{eventId};

mapper.select:
SELECT *
FROM t_article
WHERE article_type = 'REVIEW'
  AND review_type_id = #{hospitalId}
ORDER BY date_created DESC
LIMIT 20;

